25	/// Evaluate a stream of expressions.
26	fn eval_code<'a>(
27	    vm: &mut Vm,
28	    exprs: &mut impl Iterator<Item = ast::Expr<'a>>,
29	) -> SourceResult<Value> {
30	    let flow = vm.flow.take();
31	    let mut output = Value::None;
32	
33	    while let Some(expr) = exprs.next() {
34	        let span = expr.span();
35	        let value = match expr {
36	            ast::Expr::SetRule(set) => {
37	                let styles = set.eval(vm)?;
38	                if vm.flow.is_some() {
39	                    break;
40	                }
41	
42	                let tail = eval_code(vm, exprs)?.display();
43	                Value::Content(tail.styled_with_map(styles))
44	            }
45	            ast::Expr::ShowRule(show) => {
46	                let recipe = show.eval(vm)?;
47	                if vm.flow.is_some() {
48	                    break;
49	                }
50	
51	                let tail = eval_code(vm, exprs)?.display();
52	                Value::Content(tail.styled_with_recipe(
53	                    &mut vm.engine,
54	                    vm.context,
55	                    recipe,
56	                )?)
57	            }
58	            _ => expr.eval(vm)?,
59	        };
60	
61	        output = ops::join(output, value).at(span)?;
62	
63	        if let Some(event) = &vm.flow {
64	            warn_for_discarded_content(&mut vm.engine, event, &output);
65	            break;
66	        }
67	    }
68	
69	    if flow.is_some() {
70	        vm.flow = flow;
71	    }
72	
73	    Ok(output)
74	}
