77	    type Output = Value;
78	
79	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
80	        let span = self.span();
81	        let forbidden = |name| {
82	            error!(span, "{name} is only allowed directly in code and content blocks")
83	        };
84	
85	        let value = match self {
86	            Self::Text(v) => v.eval(vm).map(Value::Content),
87	            Self::Space(v) => v.eval(vm).map(Value::Content),
88	            Self::Linebreak(v) => v.eval(vm).map(Value::Content),
89	            Self::Parbreak(v) => v.eval(vm).map(Value::Content),
90	            Self::Escape(v) => v.eval(vm),
91	            Self::Shorthand(v) => v.eval(vm),
92	            Self::SmartQuote(v) => v.eval(vm).map(Value::Content),
93	            Self::Strong(v) => v.eval(vm).map(Value::Content),
94	            Self::Emph(v) => v.eval(vm).map(Value::Content),
95	            Self::Raw(v) => v.eval(vm).map(Value::Content),
96	            Self::Link(v) => v.eval(vm).map(Value::Content),
97	            Self::Label(v) => v.eval(vm),
98	            Self::Ref(v) => v.eval(vm).map(Value::Content),
99	            Self::Heading(v) => v.eval(vm).map(Value::Content),
100	            Self::ListItem(v) => v.eval(vm).map(Value::Content),
101	            Self::EnumItem(v) => v.eval(vm).map(Value::Content),
102	            Self::TermItem(v) => v.eval(vm).map(Value::Content),
103	            Self::Equation(v) => v.eval(vm).map(Value::Content),
104	            Self::Math(v) => v.eval(vm).map(Value::Content),
105	            Self::MathText(v) => v.eval(vm).map(Value::Content),
106	            Self::MathIdent(v) => v.eval(vm),
107	            Self::MathFieldAccess(v) => v.eval(vm),
108	            Self::MathShorthand(v) => v.eval(vm),
109	            Self::MathAlignPoint(v) => v.eval(vm).map(Value::Content),
110	            Self::MathCall(v) => v.eval(vm),
111	            Self::MathDelimited(v) => v.eval(vm).map(Value::Content),
112	            Self::MathAttach(v) => v.eval(vm).map(Value::Content),
113	            Self::MathPrimes(v) => v.eval(vm).map(Value::Content),
114	            Self::MathFrac(v) => v.eval(vm).map(Value::Content),
115	            Self::MathRoot(v) => v.eval(vm).map(Value::Content),
116	            Self::Ident(v) => v.eval(vm),
117	            Self::None(v) => v.eval(vm),
118	            Self::Auto(v) => v.eval(vm),
119	            Self::Bool(v) => v.eval(vm),
120	            Self::Int(v) => v.eval(vm),
121	            Self::Float(v) => v.eval(vm),
122	            Self::Numeric(v) => v.eval(vm),
123	            Self::Str(v) => v.eval(vm),
124	            Self::CodeBlock(v) => v.eval(vm),
125	            Self::ContentBlock(v) => v.eval(vm).map(Value::Content),
126	            Self::Array(v) => v.eval(vm).map(Value::Array),
127	            Self::Dict(v) => v.eval(vm).map(Value::Dict),
128	            Self::Parenthesized(v) => v.eval(vm),
129	            Self::FieldAccess(v) => v.eval(vm),
130	            Self::FuncCall(v) => v.eval(vm),
131	            Self::Closure(v) => v.eval(vm),
132	            Self::Unary(v) => v.eval(vm),
133	            Self::Binary(v) => v.eval(vm),
134	            Self::LetBinding(v) => v.eval(vm),
135	            Self::DestructAssignment(v) => v.eval(vm),
136	            Self::SetRule(_) => bail!(forbidden("set")),
137	            Self::ShowRule(_) => bail!(forbidden("show")),
138	            Self::Contextual(v) => v.eval(vm).map(Value::Content),
139	            Self::Conditional(v) => v.eval(vm),
140	            Self::WhileLoop(v) => v.eval(vm),
141	            Self::ForLoop(v) => v.eval(vm),
142	            Self::ModuleImport(v) => v.eval(vm),
143	            Self::ModuleInclude(v) => v.eval(vm).map(Value::Content),
144	            Self::LoopBreak(v) => v.eval(vm),
145	            Self::LoopContinue(v) => v.eval(vm),
146	            Self::FuncReturn(v) => v.eval(vm),
147	        }?
148	        .spanned(span);
149	
150	        // This satisfies the obligation to call `Vm::trace` for almost all
151	        // value-producing expressions!
152	        vm.trace_at(span, &value);
153	
154	        Ok(value)
155	    }
156	}
