436	/// Evaluation error for an integer literal.
437	#[cold]
438	fn int_literal_error(int: ast::Int, err: ast::IntLiteralError) -> SourceDiagnostic {
439	    let span = int.span();
440	    match err {
441	        ast::IntLiteralError::PosOverflow { base, max_plus_one: _ } => {
442	            let mut error = error!(
443	                span,
444	                "integer value is too large";
445	                hint: "value does not fit into a signed 64-bit integer";
446	            );
447	            if base.is_none() {
448	                error.hint(
449	                    "a floating point number could approximately represent this value",
450	                );
451	                error.hint(eco_format!(
452	                    "you can use a floating point number by appending a dot: `{}.`",
453	                    int.to_untyped().leaf_text()
454	                ));
455	            }
456	            error
457	        }
458	        ast::IntLiteralError::InvalidDigit(base, digits) => {
459	            let (range, bad_digits) = find_bad_digits(base, digits);
460	            // Offset by two to skip the leading `0b`/`0o`/`0x`.
461	            let sub_range = SubRange::new(range.start + 2, range.end + 2);
462	            let hint_span = DiagSpan::from_span(span, sub_range);
463	            let the_digits_are_invalid = match *bad_digits {
464	                [digit] => eco_format!("the digit `{digit}` is invalid"),
465	                [first, last] => {
466	                    eco_format!("the digits `{first}` and `{last}` are invalid")
467	                }
468	                [ref digits @ .., last] => {
469	                    eco_format!(
470	                        "the digits {}and `{last}` are invalid",
471	                        digits.iter().fold(
472	                            String::with_capacity(5 * digits.len()),
473	                            |mut buf, digit| {
474	                                let _ = write!(buf, "`{digit}`, ");
475	                                buf
476	                            }
477	                        )
478	                    )
479	                }
480	                [] => unreachable!(),
481	            };
482	            error!(
483	                span,
484	                "integer contains digits that are not valid for a{} {} number",
485	                    if base == ast::NonDecimalBase::Octal { "n" } else { "" },
486	                    base.name();
487	                hint[hint_span]: "{the_digits_are_invalid}";
488	                hint: "{} numbers only allow digits {}",
489	                    base.name(),
490	                    match base {
491	                        ast::NonDecimalBase::Hex => "0-9, a-f, A-F",
492	                        ast::NonDecimalBase::Octal => "0-7",
493	                        ast::NonDecimalBase::Binary => "0-1",
494	                    };
495	            )
496	        }
497	    }
498	}
499	
500	/// Find invalid digits for a non-decimal integer. Returns the sub-range of the
501	/// digits and a string separated by commas.
502	///
503	/// We only check for digits/letters depending on the base since the lexer
504	/// allows only ASCII digits for binary/octal, but allows ASCII letters for hex.
505	pub fn find_bad_digits(
506	    base: ast::NonDecimalBase,
507	    digits: &str,
508	) -> (Range<usize>, Vec<char>) {
509	    let ranges: &[_] = match base {
510	        ast::NonDecimalBase::Hex => &['g'..='z', 'G'..='Z'],
511	        ast::NonDecimalBase::Octal => &['8'..='9'],
512	        ast::NonDecimalBase::Binary => &['2'..='9'],
513	    };
514	    // Yield at most one copy of each digit.
515	    let iter = ranges.iter().flat_map(|range| {
516	        range.clone().filter_map(|c| digits.find(c).map(|index| (index, c)))
517	    });
518	    let mut start = digits.len();
519	    let mut end = 0;
520	    let mut bad_digits = Vec::new();
521	    for (index, digit) in iter {
522	        start = start.min(index);
523	        end = end.max(index + 1); // Equal to `digit.len_utf8()` since ASCII.
524	        bad_digits.push(digit);
525	    }
526	    (start..end, bad_digits)
527	}
