16	/// A stack of scopes.
17	#[derive(Debug, Default, Clone)]
18	pub struct Scopes<'a> {
19	    /// The active scope.
20	    pub top: Scope,
21	    /// The stack of lower scopes.
22	    pub scopes: Vec<Scope>,
23	    /// The standard library.
24	    pub base: Option<&'a Library>,
25	}
