27	impl<'a> Scopes<'a> {
28	    /// Create a new, empty hierarchy of scopes.
29	    pub fn new(base: Option<&'a Library>) -> Self {
30	        Self { top: Scope::new(), scopes: vec![], base }
31	    }
32	
33	    /// Enter a new scope.
34	    pub fn enter(&mut self) {
35	        self.scopes.push(std::mem::take(&mut self.top));
36	    }
37	
38	    /// Exit the topmost scope.
39	    ///
40	    /// This panics if no scope was entered.
41	    pub fn exit(&mut self) {
42	        self.top = self.scopes.pop().expect("no pushed scope");
43	    }
44	
45	    /// Try to access a binding immutably.
46	    pub fn get(&self, var: &str) -> HintedStrResult<&Binding> {
47	        std::iter::once(&self.top)
48	            .chain(self.scopes.iter().rev())
49	            .find_map(|scope| scope.get(var))
50	            .or_else(|| {
51	                let base = self.base?;
52	                match base.global.scope().get(var) {
53	                    Some(binding) => Some(binding),
54	                    None if var == "std" => Some(&base.std),
55	                    None => None,
56	                }
57	            })
58	            .ok_or_else(|| unknown_variable(var))
59	    }
60	
61	    /// Try to access a binding mutably.
62	    pub fn get_mut(&mut self, var: &str) -> HintedStrResult<&mut Binding> {
63	        std::iter::once(&mut self.top)
64	            .chain(&mut self.scopes.iter_mut().rev())
65	            .find_map(|scope| scope.get_mut(var))
66	            .ok_or_else(|| {
67	                match self.base.and_then(|base| base.global.scope().get(var)) {
68	                    Some(_) => cannot_mutate_constant(var),
69	                    _ if var == "std" => cannot_mutate_constant(var),
70	                    _ => unknown_variable(var),
71	                }
72	            })
73	    }
74	
75	    /// Try to access a binding immutably in math.
76	    pub fn get_in_math(&self, var: &str) -> HintedStrResult<&Binding> {
77	        std::iter::once(&self.top)
78	            .chain(self.scopes.iter().rev())
79	            .find_map(|scope| scope.get(var))
80	            .or_else(|| {
81	                let base = self.base?;
82	                match base.math.scope().get(var) {
83	                    Some(binding) => Some(binding),
84	                    None if var == "std" => Some(&base.std),
85	                    None => None,
86	                }
87	            })
88	            .ok_or_else(|| {
89	                unknown_variable_math(
90	                    var,
91	                    self.base.is_some_and(|base| base.global.scope().get(var).is_some()),
92	                )
93	            })
94	    }
95	
96	    /// Check if an std variable is shadowed.
97	    pub fn check_std_shadowed(&self, var: &str) -> bool {
98	        self.base.is_some_and(|base| base.global.scope().get(var).is_some())
99	            && std::iter::once(&self.top)
100	                .chain(self.scopes.iter().rev())
101	                .any(|scope| scope.get(var).is_some())
102	    }
103	}
