228	impl Hash for Scope {
229	    fn hash<H: Hasher>(&self, state: &mut H) {
230	        state.write_usize(self.map.len());
231	        for item in &self.map {
232	            item.hash(state);
233	        }
234	        self.deduplicate.hash(state);
235	        self.category.hash(state);
236	    }
237	}
