248	/// A bound value with metadata.
249	#[derive(Debug, Clone, Hash)]
250	pub struct Binding {
251	    /// The bound value.
252	    value: Value,
253	    /// The kind of binding, determines how the value can be accessed.
254	    kind: BindingKind,
255	    /// A span associated with the binding.
256	    span: Span,
257	    /// The category of the binding.
258	    category: Option<Category>,
259	    /// The deprecation information if this item is deprecated.
260	    deprecation: Option<Box<Deprecation>>,
261	}
262	
263	/// The different kinds of slots.
264	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
265	enum BindingKind {
266	    /// A normal, mutable binding.
267	    Normal,
268	    /// A captured copy of another variable.
269	    Captured(Capturer),
270	}
271	
272	impl Binding {
273	    /// Create a new binding with a span marking its definition site.
274	    pub fn new(value: impl IntoValue, span: Span) -> Self {
275	        Self {
276	            value: value.into_value(),
277	            span,
278	            kind: BindingKind::Normal,
279	            category: None,
280	            deprecation: None,
281	        }
282	    }
283	
284	    /// Create a binding without a span.
285	    pub fn detached(value: impl IntoValue) -> Self {
286	        Self::new(value, Span::detached())
287	    }
288	
289	    /// Marks this binding as deprecated, with the given `message`.
290	    pub fn deprecated(&mut self, deprecation: Deprecation) -> &mut Self {
291	        self.deprecation = Some(Box::new(deprecation));
292	        self
293	    }
294	
295	    /// Read the value.
296	    pub fn read(&self) -> &Value {
297	        &self.value
298	    }
299	
300	    /// Read the value, checking for deprecation.
301	    ///
302	    /// As the `sink`
303	    /// - pass `()` to ignore the message.
304	    /// - pass `(&mut engine, span)` to emit a warning into the engine.
305	    pub fn read_checked(&self, mut sink: impl WarningSink) -> &Value {
306	        if let Some(message) = &self.deprecation {
307	            sink.emit((**message).into());
308	        }
309	        &self.value
310	    }
311	
312	    /// Try to write to the value.
313	    ///
314	    /// This fails if the value is a read-only closure capture.
315	    pub fn write(&mut self) -> StrResult<&mut Value> {
316	        match self.kind {
317	            BindingKind::Normal => Ok(&mut self.value),
318	            BindingKind::Captured(capturer) => bail!(
319	                "variables from outside the {} are \
320	                 read-only and cannot be modified",
321	                match capturer {
322	                    Capturer::Function => "function",
323	                    Capturer::Context => "context expression",
324	                },
325	            ),
326	        }
327	    }
328	
329	    /// Create a copy of the binding for closure capturing.
330	    pub fn capture(&self, capturer: Capturer) -> Self {
331	        Self {
332	            kind: BindingKind::Captured(capturer),
333	            ..self.clone()
334	        }
335	    }
336	
337	    /// A span associated with the stored value.
338	    pub fn span(&self) -> Span {
339	        self.span
340	    }
341	
342	    /// A deprecation message for the value, if any.
343	    pub fn deprecation(&self) -> Option<&Deprecation> {
344	        self.deprecation.as_deref()
345	    }
346	
347	    /// The category of the value, if any.
348	    pub fn category(&self) -> Option<Category> {
349	        self.category
350	    }
351	}
352	
353	/// What the variable was captured by.
354	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
355	pub enum Capturer {
356	    /// Captured by a function / closure.
357	    Function,
358	    /// Captured by a context expression.
359	    Context,
360	}
361	
362	/// Information about a deprecated binding.
363	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
364	pub struct Deprecation {
365	    /// A deprecation message for the definition.
366	    message: &'static str,
367	    /// A version in which the deprecated binding is planned to be removed.
368	    until: Option<&'static str>,
369	}
370	
371	impl Deprecation {
372	    /// Creates new deprecation info with a default message to display when
373	    /// emitting the deprecation warning.
374	    pub fn new() -> Self {
375	        Self { message: "item is deprecated", until: None }
376	    }
377	
378	    /// Set the message to display when emitting the deprecation warning.
379	    pub fn with_message(mut self, message: &'static str) -> Self {
380	        self.message = message;
381	        self
382	    }
383	
384	    /// Set the version in which the binding is planned to be removed.
385	    pub fn with_until(mut self, version: &'static str) -> Self {
386	        self.until = Some(version);
387	        self
388	    }
389	
390	    /// The message to display when emitting the deprecation warning.
391	    pub fn message(&self) -> &'static str {
392	        self.message
393	    }
394	
395	    /// The version in which the binding is planned to be removed.
396	    pub fn until(&self) -> Option<&'static str> {
397	        self.until
398	    }
399	}
400	
401	impl Default for Deprecation {
402	    fn default() -> Self {
403	        Self::new()
404	    }
405	}
406	
407	impl From<Deprecation> for HintedString {
408	    fn from(deprecation: Deprecation) -> Self {
409	        HintedString::new(deprecation.message.into()).with_hints(
410	            deprecation
411	                .until
412	                .map(|v| eco_format!("it will be removed in Typst {v}")),
413	        )
414	    }
415	}
416	
417	/// The error message when trying to mutate a variable from the standard
418	/// library.
419	#[cold]
420	fn cannot_mutate_constant(var: &str) -> HintedString {
421	    eco_format!("cannot mutate a constant: {var}").into()
422	}
423	
424	/// The error message when a variable wasn't found.
425	#[cold]
426	fn unknown_variable(var: &str) -> HintedString {
427	    let mut res = HintedString::new(eco_format!("unknown variable: {var}"));
428	
429	    if var.contains('-') {
430	        res.hint(eco_format!(
431	            "if you meant to use subtraction, \
432	             try adding spaces around the minus sign{}: `{}`",
433	            if var.matches('-').count() > 1 { "s" } else { "" },
434	            var.replace('-', " - ")
435	        ));
436	    }
437	
438	    res
439	}
440	
441	/// The error message when a variable wasn't found it math.
442	#[cold]
443	fn unknown_variable_math(var: &str, in_global: bool) -> HintedString {
444	    let mut res = HintedString::new(eco_format!("unknown variable: {var}"));
445	
446	    if matches!(var, "none" | "auto" | "false" | "true") {
447	        res.hint(eco_format!(
448	            "if you meant to use a literal, \
449	             try adding a hash before it: `#{var}`",
450	        ));
451	    } else if in_global {
452	        res.hint(eco_format!(
453	            "`{var}` is not available directly in math, but is in the standard library",
454	        ));
455	        res.hint(eco_format!(
456	            "to access `{var}` in code mode you can add a hash: `#{var}`",
457	        ));
458	        res.hint(eco_format!(
459	            "or access `{var}` in math mode by using the `std` module: `std.{var}`",
460	        ));
461	    } else {
462	        res.hint(eco_format!(
463	            "if you meant to display multiple letters as is, \
464	             try adding spaces between each letter: `{}`",
465	            var.chars().flat_map(|c| [' ', c]).skip(1).collect::<EcoString>()
466	        ));
467	        res.hint(eco_format!(
468	            "or if you meant to display this as text, \
469	             try placing it in quotes: `\"{var}\"`"
470	        ));
471	    }
472	
473	    res
474	}
