        recipe.apply(engine, context, self)
    } else {
        Ok(self.styled(recipe))
    }
}

/// Repeat this content `count` times.
pub fn repeat(&self, count: usize) -> Self {
    Self::sequence(std::iter::repeat_with(|| self.clone()).take(count))
}

